#!/usr/bin/env dotnet
#:include *.cs
#:include Models/*.cs
#:exclude Scratch.cs

var person = new Person("Ada", "Lovelace");
Console.WriteLine(Formatter.FormatFullName(person));

static class Formatter
{
    public static string FormatFullName(Person person)
        => $"{person.FirstName} {person.LastName}".ToUpperInvariant();
}

